question.answer:
int getSum(std::vector<int> const& v) {
    auto sum = 0;
    std::for_each(v.begin(), v.end(), [&sum](auto const& value) { sum += value; });
    return sum;
}

int getMin(std::vector<int> const& v) {
    auto min = v[0];
    std::for_each(v.begin(), v.end(), [&min](auto const& value) { min = std::min(min, value); });
    return min;
}

bool hasValue(std::vector<int> const& v, int value) {
    auto it = std::find(v.begin(), v.end(), value);
    return it != v.end();
}

