question.answer:
std::vector<int> getUnique(std::vector<int> const &v)
{
    std::vector<int> unique;
    for (const auto &el : v)
    {
        if (std::find(unique.begin(), unique.end(), el) == unique.end())
        {
            unique.push_back(el);
        }
    }
    return unique;
}

