question.answer:
class Fraction {
public:
    int numerator, denominator;
    Fraction(int n, int d): numerator(n), denominator(d) {}
    virtual std::string ToString() const { return std::to_string(numerator) + " / " + std::to_string(denominator); }
};

class Decimal: public Fraction {
public:
    Decimal(int n, int d): Fraction(n, d) {}
    virtual std::string ToString() const { return std::to_string((float)numerator/(float)denominator); }
};

