cout << p2.DistanceTo(p1);

question.answer:
class Shape {
public:
    virtual double Area() const = 0;
    virtual double Perimeter() const = 0;
};

class Rectangle : public Shape {
    double width, height;
public:
    Rectangle() : width(0), height(0) {}
    Rectangle(double width, double height) : width(width), height(height) {}
    double Area() const override { return width * height; }
    double Perimeter() const override { return 2 * (width + height); }
};

class Database {
public:
    virtual void Connect() = 0;
    virtual void Query(const std::string& query) = 0;
    virtual void Close() = 0;
};

class MySQL : public Database {
    std::string dsn;
public:
    MySQL(const std::string& dsn) : dsn(dsn) {}
    void Connect() override { std::cout << "Connected to MySQL: " << dsn << std::endl; }
    void Query(const std::string& query) override { std::cout << query << std::endl; }
    void Close() override { std::cout << "Connection closed" << std::endl; }
};

testcode.text:
