questiontext.text:
Given the class

```cpp
class Date {
    int _year;
    int _month;
    int _day;
public:
    Date(int year = 1900, int month = 1, int day = 1): _year(year), _month(month), _day(day) {}
    ~Date() {}
    int GetYear() const { return _year; }
    int GetMonth() const { return _month; }
    int GetDay() const { return _day; }
};
```

Write the output operator for the `Date` class that displays the date in the format `y-m-d`.

question.answerpreload:
#include <iostream>

class Date {
    int _year;
    int _month;
    int _day;
public:
    Date(int year = 1900, int month = 1, int day = 1): _year(year), _month(month), _day(day) {}
    Date(const Date& date): _year(date._year), _month(date._month), _day(date._day) {}
    ~Date() {}
    int GetYear() const { return _year; }
    int GetMonth() const { return _month; }
    int GetDay() const { return _day; }
};

std::istream& operator>>(std::istream& in, Date& date) {
    int year, month, day;
    char separator;
    in >> year >> separator >> month >> separator >> day;
    date = Date(year, month, day);
    return in;
}

int main() {
    Date date;
    std::cin >> date;
    std::cout << date << std::endl;
    return 0;
}

question.answer:
#include <iostream>

class Date {
    int _year;
    int _month;
    int _day;
public:
    Date(int year = 1900, int month = 1, int day = 1): _year(year), _month(month), _day(day) {}
    Date(const Date& date): _year(date._year), _month(date._month), _day(date._day) {}
    ~Date() {}
    int GetYear() const { return _year; }
    int GetMonth() const { return _month; }
    int GetDay() const { return _day; }
};

std::ostream& operator<<(std::ostream& out, const Date& date) {
    out << date.GetYear() << "-" << date.GetMonth() << "-" << date.GetDay();
    return out;
}
std::istream& operator>>(std::istream& in, Date& date) {
    int year, month, day;
    char separator;
    in >> year >> separator >> month >> separator >> day;
    date = Date(year, month, day);
    return in;
}

int main() {
