question.answer:
template<class Iterator>
bool isIncreasing(Iterator begin, Iterator end) {
    Iterator next = begin;
    if(next == end) return true;
    ++ next;
    while(next != end){
        if(*begin >= *next) {
            return false;
        }
        ++ begin;
        ++ next;
    }
    return true;
}

