question.answer:
#include <iostream>
#include <algorithm>
#include <vector>

int main() {
    int N;
    std::vector<int> v;

    auto count = 0;

    std::cin >> N;
    v.resize(N);
    for(auto& element: v) {
        std::cin >> element;
    }
    for(const auto& element: v) {
        if(element % 2 == 0) {
            std::cout << element << " ";
            ++count;
        }
    }

    if(count == 0) {
        std::cout << "oops!" << std::endl;
    }
    return 0;
}

