#include <iostream>
#include <vector>
#include <algorithm>

int main() {
	int N, M;
	std::vector<int> a;
	std::cin >> N;
	a.resize(N, 0);
	for(int i = 0; i < N; ++i) {
		std::cin >> a[i];
	}
	std::cin >> M;

	auto it = std::find(a.begin(), a.end(), M);
	if(it == a.end()) {
		std::cout << -1;
	}
	else {
		std::cout << it - a.begin();
	}
	return 0;
}

