question.answer:
#include <iostream>
#include <vector>

int main() {
    int N;
    std::vector<int> v;

    auto count = 0;

    std::cin >> N;
    v.resize(N);
    for(auto& element: v) {
        std::cin >> element;
    }

    for(int i = 0; i < N; ++i) {
        bool candidate = true;
        if(i > 0 && v[i] <= v[i - 1]) {
            candidate = false;
        }
        if(i < N - 1 && v[i] <= v[i + 1]) {
            candidate = false;
        }
        if(candidate) {
            ++count;
        }
    }

    std::cout << count;
    return 0;
}

