int main() {
    int N, B;
    std::vector<int> v;

    std::cin >> N;
    v.resize(N);
    for(auto& element: v) {
        std::cin >> element;
    }
    std::cin >> B;

    auto it = std::remove(v.begin(), v.end(), B);
    v.resize(it - v.begin());
    for(const auto& element: v) {
        std::cout << element << " ";
    }
    if(v.size() == 0) { std::cout << "oops!"; }
    return 0;
}

